/**
 * Looks up the CEST code for a given NCM.
 * The NCM can be in any format (with or without dots).
 * Returns the formatted CEST (XX.XXX.XX) or null if not found.
 */
export function lookupCestByNcm(ncm: string): string | null {
  const clean = ncm.replace(/\D/g, "");
  if (clean.length === 0) return null;

  const formatted =
    clean.length >= 8
      ? clean.substring(0, 4) + "." + clean.substring(4, 6) + "." + clean.substring(6, 8)
      : null;

  // Try exact match first (full 8-digit NCM)
  if (formatted && NCM_CEST_EXACT[formatted]) {
    return NCM_CEST_EXACT[formatted];
  }

  // Try prefix match (longest prefix wins)
  for (const entry of NCM_CEST_PREFIX) {
    if (clean.startsWith(entry.prefix)) {
      return entry.cest;
    }
  }

  return null;
}
